!function(){"use strict";var e=window.IWACVis=window.IWACVis||{};e.locale="fr"===(document.documentElement.getAttribute("lang")||"en").toLowerCase().split(/[-_]/)[0]?"fr":"en";var t={en:{"Visualization data is not available yet.":"The data for this visualisation has not been published yet.",desc_publication_run:"Issues of this periodical per year. The dot marks this issue.",desc_publication_similar:"Issues whose tables of contents most resemble this one, compared by an AI model (Gemini).",desc_publication_wordcloud:"The words that appear most often in this issue’s text.",desc_word_cloud:"The most frequent words, sized by how often they appear.",period_covered:"Period covered: {min} – {max}",coverage_range:"{min} – {max}",window_note:"Showing {shown} of {total} rows.",window_all:"Showing all {total} rows.",window_show_all:"Show all {total}",window_show_top:"Show first {shown}",gantt_window_note:"Showing the {shown} best-covered of {total} newspapers.",gantt_window_all:"Showing all {total} newspapers.",gantt_show_all:"Show all {total}",gantt_show_top:"Show top {shown}",chart_aria_plain:"{title}: chart.",chart_aria_single:"{title}: chart with {points} values.",chart_aria_summary:"{title}: chart with {series} series and {points} values.",chart_aria_zoom:"Focus the chart and use the arrow keys to move the visible window.",references_provenance_desc:"Places of publication recorded on the references, shown wherever the place could be matched to map coordinates.",references_subject_cooccurrence_desc:"Pairs of subject tags that appear together on the same reference.","Full-text coverage":"Full-text coverage",references_coverage_desc:"How many references have their full text available as searchable text, by kind of publication.",references_coverage_desc_full:"Full text has been extracted for {withOcr} of {total} references ({pct}%): {words} words in all, and {median} in a typical reference. The topic panels below describe that digitised part of the bibliography rather than the whole of it. Each bar shows the digitised count for one kind of publication against its total. Of these references, {published} also have their text published on islam.zmo.de; the others feed the aggregate figures here without being readable in full.",references_coverage_tooltip:"{withOcr} of {total} with full text ({pct}%)","Semantic landscape of the literature":"Semantic landscape of the literature",references_landscape_desc:"Each point is one reference, placed according to how similar its full text is to the others. Works sitting close together are ones the AI model reads as being about the same thing. Drag to move around the map, scroll to zoom, and click a point to open the reference.",references_landscape_desc_full:"Each point is one reference, placed according to how similar its full text is to the others: an AI model compares the texts, and a technique called UMAP flattens those comparisons onto two dimensions. Works sitting close together are ones the model reads as being about the same thing. The axes have no units, and the distance between two clusters means nothing; only which points sit near which. The map covers the {embedded} of {total} references ({pct}%) whose full text has been extracted, and that subset reflects what the collection was able to obtain and digitise rather than a representative sample. Drag to move around the map, scroll to zoom, and click a point to open the reference.",references_landscape_empty:"No semantic map is available for this bibliography",references_landscape_empty_umap:"The semantic map was not computed: the umap-learn package was missing when this data was built",references_landscape_empty_few:"Too few references have extracted full text to draw a meaningful map","Color by":"Colour by",Decade:"Decade",Type:"Type","Scholarly topics":"Scholarly topics",references_topics_title_lang:"Scholarly topics ({language})",references_topics_desc:"Themes found automatically in the full text of {count} references by a statistical model (LDA), which sorted them into {topics} topics. Each label lists the words most characteristic of its topic; the labels come from the model rather than from a cataloguer. Each language has its own model, so topic numbers cannot be compared between these panels. Hover over a bar for the references most typical of that topic.",references_topic_tooltip:"{count} references ({pct}% of this model’s corpus). Most representative:","Languages studied":"Languages","Fetching references…":"Fetching references…","ref_type_Article de revue":"Journal article",ref_type_Chapitre:"Book chapter",ref_type_Livre:"Book","ref_type_Ouvrage collectif":"Edited volume","ref_type_Thèse":"Thesis","ref_type_Mémoire":"Master’s thesis",ref_type_Communication:"Conference paper",ref_type_Rapport:"Report","ref_type_Présentation":"Presentation","ref_type_Compte rendu":"Review","ref_type_Article de journal":"Newspaper article","ref_type_Billet de blog":"Blog post","ref_type_Article de blog":"Blog post","ref_type_Page web":"Web page",ref_type_Document:"Document",ref_type_Unknown:"Unknown",lang_Anglais:"English","lang_Français":"French",lang_Allemand:"German",lang_Italien:"Italian",lang_Espagnol:"Spanish","lang_Slovène":"Slovenian",lang_Arabe:"Arabic",lang_Portugais:"Portuguese","lang_Néerlandais":"Dutch",items_count:"{count} items",articles_count:"{count} articles",publications_count:"{count} publications",references_count:"{count} references",mentions_count:"{count} mentions","References count":"References",source_locations_desc:"Archives, repositories, web platforms and publication sources linked to collection items.",source_map_summary:"{sources} sources · {mapped} mapped · {items} source-linked items",item_type_article:"News article",item_type_publication:"Islamic periodical",item_type_document:"Document",item_type_audiovisual:"Audio-visual recording",item_type_reference:"Reference",item_type_image:"Photograph","Period covered_short":"Years",desc_mentions_timeline:"Articles, publications and references mentioning this person each year, stacked by country of publication.",desc_top_newspapers:"News and periodical sources where this person appears most often (top 15).",desc_countries_covered:"Distribution of mentions by country of publication of the source.",desc_associated_entities:"The entities that appear most distinctively alongside this person. The ranking (TF-IDF) favours names peculiar to this person over names that turn up everywhere in the collection. Network reveals clusters; Relational list gives the exact ranking and joins entities that repeatedly appear together; Over time shows when the shared items were published. Filter by authority type or change how many are shown.",desc_associated_locations:"Places mentioned in items where this person appears as creator or subject, taken from each item’s spatial coverage field and from place tags matched against the IWAC authority list.",desc_year_month_heatmap:"Mentions per year and month, counted only for items whose date gives at least a year and a month. Cells stay blank where no date could be read.",desc_lda_topics:"The 12 most common themes among articles mentioning this entity, by article count. The themes come from a statistical model (LDA) run over the articles in the collection; publications and references add to the mention counts but not to the topic mix.",desc_ai_sentiment:"Polarity and centrality of articles mentioning this entity, as rated by each AI model in turn. The model picker switches between them and the bars update in place. Articles only: publications and references are not rated.",desc_subject_cooccurrence:"How often each pair among the 15 entities most often mentioned alongside this one appears together. The Associated entities panel puts this entity at the centre and measures the links to it; this panel sets the centre aside and asks which neighbours keep travelling together.","Très positif":"Very positive",Positif:"Positive",Neutre:"Neutral","Négatif":"Negative","Très négatif":"Very negative","Non applicable":"Not applicable","Très central":"Very central",Secondaire:"Secondary","Non abordé":"Not addressed",1:"Very objective",2:"Rather objective",3:"Mixed",4:"Rather subjective",5:"Very subjective",desc_entity_mentions_timeline:"Articles, publications and references mentioning this entity each year, stacked by country of publication.",desc_entity_top_newspapers:"News and periodical sources where this entity is named most often (top 15).",desc_entity_countries_covered:"Distribution of mentions by country of publication of the source.",desc_entity_associated_entities:"The entities that appear most distinctively alongside this one. The ranking (TF-IDF) favours names peculiar to this entity over names that turn up everywhere in the collection. Network reveals clusters; Relational list gives the exact ranking and joins entities that repeatedly appear together; Over time shows when the shared items were published. Filter by authority type or change how many are shown.",desc_entity_associated_locations:"Places mentioned in the same items as this entity, taken from each item’s spatial coverage field and from place tags matched against the IWAC authority list.",shared_items_count:"{count} shared items",connections_count:"{count} connections",one_connection:"1 connection",and_n_more:"and {count} more","Network view":"Network","Relational list":"Relational list","Over time":"Over time","All entities":"All","Number shown":"Number shown",Period:"Period","Five-year periods":"Five-year periods",Decades:"Decades","Distinctiveness ranking":"Distinctiveness ranking","Associated entities over time":"Associated entities over time","Overall mentions":"Overall mentions",shared_items_in_period:"{count} shared items, {period}","Ranked by distinctiveness. Curves connect entities that repeatedly appear together.":"Ranked by distinctiveness. Curves connect entities that repeatedly appear together.","Rows retain the overall distinctiveness ranking. Each cell counts shared items with a readable year.":"Rows retain the overall distinctiveness ranking. Each cell counts shared items with a readable year.","Darker cells represent more shared items.":"Darker cells represent more shared items.","Items without a readable year are omitted: {count}.":"Items without a readable year are omitted: {count}.",entity_type_center:"Centre",entity_type_Personnes:"Persons",entity_type_Organisations:"Organisations",Organizations:"Organisations",entity_type_Lieux:"Places",entity_type_Sujets:"Subjects","entity_type_Événements":"Events",entity_type_article:"Newspaper article",desc_article_context_network:"This article sits at the centre, surrounded by the people, places, organisations and subjects tagged in it. Articles that share several of those tags appear around the edge. Drag a node to rearrange the graph, or click one to see its connections and a link to its page.",desc_article_further_reading:"Other material from the collection that connects to this article. Use the tabs to switch between the ways of finding it.",desc_further_reading_tags:"Articles tagged with the same people, places, organisations or subjects as this one. The badge shows how many tags they share.",desc_further_reading_scholarship:"Scholarly works in the IWAC bibliography whose text reads like this article: the academic literature around what it covers. This uses the same AI comparison as the previous tab, run across the two collections. Treat each result as a lead to follow rather than a citation, since a long work compared in summary can look close to many articles at once.",desc_further_reading_content:"Articles whose full text reads similarly to this one, even when they don’t share any tags. The match is computed by an AI language model that turns each article into a numeric fingerprint (a “semantic embedding”) and compares them. The badge shows how close the match is.",shares_n_entities:"{count} shared tags","No related articles":"No articles with shared tags","No entities tagged":"No entities tagged on this article","Only in A":"Only in {name}","Only in B":"Only in {name}","Single-newspaper corpus — no breakdown":"Single-newspaper corpus: no breakdown","Sentiment only on articles":"Sentiment ratings cover articles only","Places mentioned in each corpus, joined to the IWAC authority index. Bubble size scales with the number of items that tagged each place.":"Places mentioned in each corpus, matched against the IWAC authority index. The larger the bubble, the more items tagged that place.","Distribution of polarity and centrality in articles of each corpus, as rated by the AI models. The picker swaps the model; publications are not rated.":"How polarity and centrality are distributed across the articles of each corpus, as rated by the AI models. Use the picker to change model; publications are not rated.","Scales: polarity 1 (very negative) – 5 (very positive) · centrality 1 (not addressed) – 5 (very central) · subjectivity 1 (objective) – 5 (subjective)":"Scales: polarity 1 (very negative) – 5 (very positive) · centrality 1 (not addressed) – 5 (very central) · subjectivity 1 (objective) – 5 (subjective)","Diverging A minus B":"Difference: A minus B",desc_minimal_sparkline:"Where this item sits in its collection’s activity over time. The dot marks the year of the current item.",desc_minimal_similar:"Other items in the same IWAC subset, most recent first. Click an item to open its page.",desc_minimal_similar_semantic:"Photographs an AI model reads as closest to this one. It compares the images themselves, so the resemblance is visual and thematic rather than a matter of shared catalogue records. The percentage is the similarity score.",desc_minimal_sparkline_scoped:"When this channel or collection published, year by year. The dot marks the year of the current item.",desc_minimal_similar_scoped:"Other recordings from the same channel or collection, most recent first. Click one to open its page.",items_from_source:"{count} items from {source}",hours_count:"{count} h",minutes_count:"{count} min",desc_horizontal_bar:"Top values by count, ranked from highest to lowest.",desc_topic_treemap:"Each rectangle is one of the 30 topics found by the model; its area reflects how many articles were assigned to that topic. Click a rectangle to open the topic in detail.",cal_panel_title:"Publication calendar",desc_topic_calendar:"When articles classified into this topic were published. Only articles with a full date, down to the day, appear here; those dated to a year or a month alone are left out rather than placed on 1 January.",topic_copy_link:"Copy link to this topic",topic_link_copied:"Link copied",desc_topic_countries:"Distribution of articles in this topic by country of publication.",desc_topic_newspapers:"Newspapers and periodicals where this topic appears most often.",desc_topic_top_articles:"Articles the model attached most strongly to this topic, ranked by how confident it was.",desc_article_spatial:"Places tagged on this article, located through the IWAC authority index. Every pin is one place mentioned once, so all pins are the same size. Click a pin to open the place’s record.",article_place_subtitle:"Mentioned in this article","No geocoded places":"No places on this article could be located",Authors:"Authors",Publisher:"Publisher",DOI:"DOI","This work in the bibliography":"This work in the bibliography","Closest works in the bibliography":"Closest works in the bibliography","Press coverage this resembles":"Press coverage this resembles",desc_reference_activity:"Where this work sits in the IWAC bibliography’s own publication timeline. The dot marks its year.",desc_reference_similar:"Works in the bibliography whose text reads most like this one, compared by an AI language model rather than by shared subject headings. Only works with extracted full text can appear, which is about half the bibliography.",desc_reference_press:"Newspaper articles from the collection whose text reads like this work: the press coverage around what it studies. A scholarly work is long and was compared in summary, so read these as leads rather than as citations.",reference_topic_label:"Topic",reference_topic_model:"Machine-generated topic words, from the model “{model}”. Each language has its own model, so topic numbers are not comparable across them.",reference_topic_generated:"Machine-generated topic words, not curated subject headings.",reference_reviews_prefix:"Reviews:",reference_reviewed_by_prefix:"Reviewed in:","Loading distinctive vocabulary":"Loading distinctive vocabulary","Distinctive vocabulary":"Distinctive vocabulary","Coverage bursts":"Coverage bursts",keyness_title:"Words that set this part of the collection apart",keyness_desc:"Words used at least {ratio}× more often here than in the rest of the collection. Each bar shows the size of that difference, and the label gives the multiplier. Only differences unlikely to be down to chance appear (false-discovery rate {alpha}; a word needs at least {min} occurrences here to qualify). Distinctive is not the same as frequent: a word can be common everywhere and stand out nowhere.",keyness_slice_caption:"{slice}: {docs} articles, {tokens} words, {terms} distinctive terms.",keyness_axis:"Times more frequent than elsewhere (log₂)",keyness_tooltip_ratio:"Used {ratio}× as often as in the rest of the collection",keyness_tooltip_count:"{count} occurrences in {slice}",keyness_tooltip_stats:"Log-likelihood G² {g2}, corrected p {q}",bursts_title:"When coverage of a subject surged",bursts_desc:"Periods when a subject was tagged on far more articles than its own long-run rate, roughly {s}× that rate or above. The episodes are found automatically, without the software being told what to look for. Each bar is one episode, and the same subject can surge more than once. A subject needs at least {min} tagged articles before its baseline is steady enough to test against. A subject that simply enters the index and stays in use does not count: that is its arrival in the cataloguing vocabulary rather than a change in coverage.",bursts_caption:"{bursts} episodes across {subjects} subjects ({found} of {tested} tested subjects burst at all).",bursts_tooltip_span:"Burst: {start}–{end}",bursts_tooltip_mentions:"{mentions} of the subject’s {total} articles fall in this burst",bursts_tooltip_weight:"Burst strength {weight}",topics_over_time_title:"Topics over time",topics_over_time_desc:"How the attention of the press shifted across themes (the 12 largest topics; the rest fold into “Other topics”). Click a band to open that topic.",topic_other:"Other topics",topics_weighting_dominant:"Dominant topic",topics_weighting_weighted:"Probability-weighted",topics_over_time_dominant_note:"Each band is a topic’s share of the articles it was the single best label for that year, so every year sums to 100%. An article the model split evenly between three topics counts wholly for one of them.",topics_over_time_weighted_note:"Each band is the average probability the model assigned to that topic across the year’s articles, so an evenly split article contributes to all three of its topics. Only the top {k} topics of each article are recorded, so the stack tops out around {mass}% rather than 100%. The gap is thematic weight spread too thinly to be stored, and not articles left unclassified.",desc_calendar_heatmap:"How densely publications fall over time. The darker the cell, the higher the count. The colours match the other heatmaps on this site so the two can be read side by side.",cal_view_month:"By month",cal_view_day:"By day",cal_view_hijri:"By Hijri month",cal_hijri_era:"AH",cal_month_note:"One column per year, one row per calendar month.",cal_day_note:"One cell per day, one block per year. Useful for spotting the surge around a single event, at the cost of a lot of empty grid.",cal_hijri_note:"Publication dates converted to the Islamic calendar with the Umm al-Qura tables, so Ramadan and Dhu al-Hijja hold still as rows instead of drifting eleven days a year across the Gregorian grid. Month boundaries in West Africa were set by local moon sighting and often fell a day either side of the tabular date, so a cell at the very start or end of a month may belong to its neighbour.",cal_skipped_note:"{count} could not be converted and are not shown.",cal_hijri_coverage:"Only a complete day-precision date converts to a lunar one, so this grid covers {shown} of the {total} mentions the Gregorian view shows.",desc_chord:"Links between the entities most often mentioned in this set, laid out in a circle. The thicker the ribbon, the more often the two are mentioned together. Only the 30 best-connected entities are drawn, so the diagram stays legible.",desc_radar_profile:"Side-by-side comparison along three or more axes. Each axis is scaled on its own, so the shapes stay comparable even when one measure is far larger than the others.",desc_sibling_sparkline:"Activity over time for the parent collection, such as this article within its newspaper’s timeline. The dot marks the current item.",desc_similar_items:"Articles whose full text an AI model reads as closest to this one, ranked by how close the match is. Weak matches are hidden, so very short articles do not produce misleading neighbours.",desc_sunburst:"A breakdown by level, drawn as concentric rings. Each ring is one level, and the longer the arc, the higher the count.",desc_treemap:"A breakdown by level, drawn as nested rectangles. Click a rectangle to open it; the trail at the bottom leads back up.","Explore the prevalence of Dublin Core Subject and Spatial Coverage fields over time.":"How often the collection’s Subject and Spatial Coverage tags are used over time. The counts measure cataloguing rather than wording: an item tagged “Terrorism” adds one mention to its year, however many times the word appears in the text.","Top entities":"Most frequent entities in Dublin Core Subject and Spatial Coverage",desc_top_entities:"Authority records that appear most often in item-level Dublin Core Subject (dcterms:subject) and Spatial Coverage (dcterms:spatial) fields. Click a bar to open the entity’s page.",desc_lifespan:"Each point is one entity. The horizontal axis is the span in years between its first and last appearance, the vertical axis its total number of mentions, and the colour shows the entity type. Click a point to open the entity.",desc_temporal_extent:"First and last year each top entity appears in the corpus (up to 30 per type, ranked by frequency). Each bar spans from earliest to latest mention.",desc_places_map:"Two complementary layers on the same map. Authority pins: every place in the IWAC authority index that has geographic coordinates. Mention bubbles: how often each place is tagged in an item’s Dublin Core Spatial Coverage field, joined back to the authority pin by name. Click a pin to open the place’s page.","Top frequent":"Most frequent",top_n_keywords:"{count} keywords",select_up_to_n:"Select up to {count} keywords",top_n_over_time:"Top {count} keywords over time",desc_subjects_bump:"Rank of the leading subjects in each decade. A line that climbs is a subject gaining ground on those below it. A line breaks where the subject drops out of the decade’s top eight; hover over a decade for ranks and counts.",desc_geo_attention:"How much attention the press gave each country over time, measured by how often articles were catalogued as being about it. Drag the year slider or press play. The colour scale is the same in every year, so a darker country always means heavier coverage, whatever year you are viewing.",spatial_pick_hint:"Pick an entity to map the places mentioned alongside it. Without a selection, the map shows every place in the collection.",places_count:"{count} places",spatial_map_description:"The larger the bubble, the more often the place is mentioned. Hover over a place for a preview, or click it for the full list of items.",admin_units_count:"{count} units",more_items_click:"{count} more — click for the full list",networks_description:"Entities that appear in the same items, placed closer together the more often they are mentioned together. Click a node to see its connections.",network_select_hint:"Click a node to see its strongest co-occurrences; click the background to clear.",network_stats_entities:"{nodes} entities · {links} links",network_stats_places:"{nodes} places · {links} links",network_links_note:"A link joins two entities that appear in the same item at least {count} times.",cooccurrence_title:"Co-occur in {count} items",more_links_count:"+{count} more links",links_count:"{count} links"},fr:{"Loading dashboard":"Chargement du tableau de bord","Loading collection overview":"Chargement de la vue d’ensemble","Loading project comparison":"Chargement de la comparaison","Loading newspaper comparison":"Chargement de la comparaison des journaux",Dashboard:"Tableau de bord",Visualizations:"Visualisations","Knowledge Graph":"Graphe de connaissances","Save as image":"Enregistrer comme image","Download chart":"Télécharger le graphique","Copy embed code":"Copier le code d’intégration","Copied!":"Copié !","Show patterns":"Afficher les motifs","Hide patterns":"Masquer les motifs","No data available":"Aucune donnée disponible","Failed to load":"Le chargement a échoué","Visualization data is not available yet.":"Les données de visualisation ne sont pas encore disponibles.",Count:"Nombre",Year:"Année",Total:"Total","Logarithmic scale":"Échelle logarithmique","Total items":"Total d’items",Articles:"Articles",Publications:"Publications",Documents:"Documents",Audiovisual:"Audiovisuel",References:"Références",Entities:"Entités",Countries:"Pays",Languages:"Langues",Words:"Mots",Newspapers:"Journaux",Unknown:"Inconnu",Pages:"Pages",Issue:"Numéro",Language:"Langue",Date:"Date","This issue in its periodical run":"Ce numéro dans la collection du périodique",desc_publication_run:"Numéros de ce périodique par année. Le point marque ce numéro.","Similar issues":"Numéros similaires",desc_publication_similar:"Numéros dont le sommaire ressemble le plus à celui-ci, rapprochés par un modèle d’IA (Gemini).","Most frequent words in this issue":"Mots les plus fréquents de ce numéro",desc_publication_wordcloud:"Les mots qui reviennent le plus souvent dans le texte de ce numéro.","Word cloud":"Nuage de mots",desc_word_cloud:"Les mots les plus fréquents, dimensionnés selon le nombre de leurs occurrences.","Items per year, by country":"Éléments par année, par pays","Content by country":"Contenu par pays","Languages represented":"Langues représentées","Most-cited entities":"Entités les plus citées","Newspaper coverage":"Couverture des journaux","Collection breakdown":"Répartition de la collection",period_covered:"Période couverte : {min} – {max}",coverage_range:"{min} – {max}",window_note:"Affichage de {shown} lignes sur {total}.",window_all:"Affichage des {total} lignes.",window_show_all:"Afficher les {total}",window_show_top:"Afficher les {shown} premières",gantt_window_note:"Affichage des {shown} journaux les mieux couverts sur {total}.",gantt_window_all:"Affichage des {total} journaux.",gantt_show_all:"Afficher les {total}",gantt_show_top:"Afficher les {shown} premiers",chart_aria_plain:"{title} : graphique.",chart_aria_single:"{title} : graphique de {points} valeurs.",chart_aria_summary:"{title} : graphique de {series} séries et {points} valeurs.",chart_aria_zoom:"Placez le focus sur le graphique et utilisez les touches fléchées pour déplacer la fenêtre visible.",Chart:"Graphique",Filters:"Filtres",Persons:"Personnes",Organizations:"Organisations",Places:"Lieux",Subjects:"Sujets",Events:"Événements",Authors:"Auteurs",Publishers:"Éditeurs","Reference type":"Type de référence","Reference types":"Types de référence","References by type over time":"Références par type dans le temps","Top authors":"Auteurs les plus cités","Top publishers":"Éditeurs les plus cités","Top subjects":"Sujets récurrents","Reference provenance":"Provenance des références",references_provenance_desc:"Lieux de publication indiqués sur les références, affichés lorsque le lieu a pu être associé à des coordonnées cartographiques.",references_subject_cooccurrence_desc:"Paires de sujets apparaissant ensemble sur une même référence.","No provenance locations available":"Aucun lieu de provenance disponible","No subject co-occurrence available":"Aucune cooccurrence de sujets disponible","Full-text coverage":"Couverture en texte intégral",references_coverage_desc:"Nombre de références dont le texte intégral est disponible sous forme de texte interrogeable, par type de publication.",references_coverage_desc_full:"Le texte intégral a été extrait pour {withOcr} références sur {total} ({pct} %), soit {words} mots au total et {median} pour une référence typique. Les panneaux de thèmes ci-dessous décrivent cette partie numérisée de la bibliographie plutôt que son ensemble. Chaque barre indique le nombre de références numérisées pour un type de publication, rapporté à son total. Parmi ces références, {published} ont aussi leur texte publié sur islam.zmo.de ; les autres alimentent les chiffres agrégés présentés ici sans être consultables intégralement.",references_coverage_tooltip:"{withOcr} sur {total} avec texte intégral ({pct} %)","Semantic landscape of the literature":"Paysage sémantique de la littérature scientifique",references_landscape_desc:"Chaque point est une référence, positionnée selon la ressemblance de son texte intégral avec celui des autres. Les travaux qui se retrouvent voisins sont ceux que le modèle d’IA lit comme portant sur le même objet. Faites glisser pour vous déplacer sur la carte, utilisez la molette pour zoomer et cliquez sur un point pour ouvrir la référence.",references_landscape_desc_full:"Chaque point est une référence, positionnée selon la ressemblance de son texte intégral avec celui des autres. Un modèle d’IA compare les textes, puis une technique appelée UMAP ramène ces comparaisons à deux dimensions. Les travaux qui se retrouvent voisins sont ceux que le modèle lit comme portant sur le même objet. Les axes n’ont pas d’unité et la distance entre deux grappes ne signifie rien ; seul compte le voisinage. La carte couvre les {embedded} références sur {total} ({pct} %) dont le texte intégral a été extrait, un sous-ensemble qui reflète ce que la collection a pu obtenir et numériser plutôt qu’un échantillon représentatif. Faites glisser pour vous déplacer sur la carte, utilisez la molette pour zoomer et cliquez sur un point pour ouvrir la référence.",references_landscape_empty:"Aucune carte sémantique disponible pour cette bibliographie",references_landscape_empty_umap:"La carte sémantique n’a pas été calculée, faute du paquet umap-learn lors de la construction de ces données",references_landscape_empty_few:"Trop peu de références disposent d’un texte intégral extrait pour tracer une carte significative","Color by":"Colorer par",Decade:"Décennie","Scholarly topics":"Thèmes de la littérature scientifique",references_topics_title_lang:"Thèmes de la littérature scientifique ({language})",references_topics_desc:"Thèmes dégagés automatiquement dans le texte intégral de {count} références par un modèle statistique (LDA), qui les a réparties en {topics} thèmes. Chaque libellé reprend les mots les plus caractéristiques de son thème ; ces libellés viennent du modèle plutôt que d’un catalogueur. Chaque langue a son propre modèle, si bien que les numéros de thèmes ne sont pas comparables d’un panneau à l’autre. Survolez une barre pour voir les références les plus représentatives du thème.",references_topic_tooltip:"{count} références ({pct} % du corpus de ce modèle). Les plus représentatives :","Languages studied":"Langues","Places studied":"Lieux étudiés","Fetching references…":"Récupération des références…","ref_type_Article de revue":"Article de revue",ref_type_Chapitre:"Chapitre",ref_type_Livre:"Livre","ref_type_Ouvrage collectif":"Ouvrage collectif","ref_type_Thèse":"Thèse","ref_type_Mémoire":"Mémoire",ref_type_Communication:"Communication",ref_type_Rapport:"Rapport","ref_type_Présentation":"Présentation","ref_type_Compte rendu":"Compte rendu","ref_type_Article de journal":"Article de journal","ref_type_Billet de blog":"Billet de blog","ref_type_Article de blog":"Article de blog","ref_type_Page web":"Page web",ref_type_Document:"Document",ref_type_Unknown:"Inconnu",lang_Anglais:"Anglais","lang_Français":"Français",lang_Allemand:"Allemand",lang_Italien:"Italien",lang_Espagnol:"Espagnol","lang_Slovène":"Slovène",lang_Arabe:"Arabe",lang_Portugais:"Portugais","lang_Néerlandais":"Néerlandais","Author collaborations":"Collaborations entre auteurs","Co-author":"Co-auteur","Author / editor":"Auteur / éditeur","Shared references":"Références communes",items_count:"{count} éléments",articles_count:"{count} articles",publications_count:"{count} publications",references_count:"{count} références",mentions_count:"{count} mentions",Index:"Index","Total words":"Mots totaux","Total pages":"Pages totales","Scanned pages":"Pages numérisées","Unique sources":"Sources uniques","Document types":"Types de documents","Audiovisual minutes":"Minutes audiovisuelles","References count":"Références","Recent additions":"Ajouts récents","Collection growth over time":"Croissance de la collection dans le temps","Items by type, over time":"Éléments par type, dans le temps","French word cloud":"Nuage de mots français","World map":"Carte du monde","Source locations":"Localisation des sources",source_locations_desc:"Archives, dépôts, plateformes web et sources de publication associés aux éléments de la collection.",source_map_summary:"{sources} sources · {mapped} localisées · {items} éléments liés à une source","No mapped sources":"Aucune source localisée",Global:"Global","By type":"Par type","By country":"Par pays","By year":"Par année","All countries":"Tous les pays","All types":"Tous les types",Country:"Pays",Other:"Autre",Previous:"Précédent",Next:"Suivant",Page:"Page",Title:"Titre",Source:"Source",Type:"Type",Coordinates:"Coordonnées",Added:"Ajouté",Month:"Mois",Monthly:"Mensuel",Cumulative:"Cumulé","Monthly additions":"Ajouts mensuels","Cumulative total":"Total cumulé","No recent additions":"Aucun ajout récent",Loading:"Chargement","unique words":"mots uniques","Map library unavailable":"Bibliothèque de cartographie indisponible","Loading map":"Chargement de la carte",item_type_article:"Article de presse",item_type_publication:"Périodique islamique",item_type_document:"Document",item_type_audiovisual:"Enregistrement audio-visuel",item_type_reference:"Référence",item_type_image:"Photographie",Mentions:"Mentions","Total mentions":"Mentions totales","All roles":"Tous les rôles","As subject":"Comme sujet","As creator":"Comme créateur","As editor":"Comme éditeur","Associated entities":"Entités associées","Associated locations":"Lieux associés","Top newspapers":"Journaux les plus fréquents","Countries covered":"Pays couverts","Period covered_short":"Années","Distinctiveness score":"Indice de spécificité",Affiliations:"Affiliations",Wikidata:"Wikidata",desc_mentions_timeline:"Nombre d’articles, publications et références mentionnant cette personne par année, empilé par pays de publication.",desc_top_newspapers:"Journaux et périodiques où cette personne apparaît le plus souvent (top 15).",desc_countries_covered:"Répartition des mentions par pays de publication de la source.",desc_associated_entities:"Les entités qui apparaissent le plus distinctement aux côtés de cette personne. Le classement (TF-IDF) privilégie les noms qui lui sont propres sur ceux qui reviennent partout dans la collection. Réseau révèle les groupes ; Liste relationnelle donne le classement exact et relie les entités qui reviennent ensemble ; Dans le temps indique quand les documents en commun ont été publiés. Filtrez par type de notice d’autorité ou modifiez le nombre affiché.",desc_associated_locations:"Lieux mentionnés dans les notices où cette personne apparaît comme créateur ou sujet, tirés du champ de couverture spatiale et des balises de lieux rapprochées de la liste d’autorité IWAC.",desc_entity_mentions_timeline:"Nombre d’articles, publications et références mentionnant cette entité par année, empilé par pays de publication.",desc_entity_top_newspapers:"Journaux et périodiques où cette entité est nommée le plus souvent (top 15).",desc_entity_countries_covered:"Répartition des mentions par pays de publication de la source.",desc_entity_associated_entities:"Les entités qui apparaissent le plus distinctement aux côtés de celle-ci. Le classement (TF-IDF) privilégie les noms qui lui sont propres sur ceux qui reviennent partout dans la collection. Réseau révèle les groupes ; Liste relationnelle donne le classement exact et relie les entités qui reviennent ensemble ; Dans le temps indique quand les documents en commun ont été publiés. Filtrez par type de notice d’autorité ou modifiez le nombre affiché.",desc_entity_associated_locations:"Lieux mentionnés dans les mêmes notices que cette entité, tirés du champ de couverture spatiale et des balises de lieux rapprochées de la liste d’autorité IWAC.","Year × month heatmap":"Carte de chaleur année × mois","Top LDA topics":"Principaux thèmes","AI sentiment":"Sentiment IA","Subject co-occurrence":"Co-occurrence de sujets",desc_year_month_heatmap:"Nombre de mentions par année et par mois, calculé uniquement à partir des notices dont la date donne au moins une année et un mois. Les cellules restent vides là où aucune date n’a pu être lue.",desc_lda_topics:"Les 12 thèmes les plus fréquents parmi les articles mentionnant cette entité, par nombre d’articles. Ces thèmes proviennent d’un modèle statistique (LDA) appliqué aux articles de la collection ; publications et références alimentent le nombre de mentions mais pas la répartition thématique.",desc_ai_sentiment:"Polarité et centralité des articles mentionnant cette entité, évaluées tour à tour par chaque modèle d’IA. Le sélecteur de modèle bascule entre eux et les barres se mettent à jour sur place. Articles uniquement, les publications et les références n’étant pas évaluées.",desc_subject_cooccurrence:"Fréquence à laquelle chaque paire, parmi les 15 entités les plus souvent mentionnées aux côtés de celle-ci, apparaît ensemble. Le panneau Entités associées place cette entité au centre et mesure les liens qui y aboutissent ; celui-ci écarte le centre et demande quels voisins voyagent toujours ensemble.",Polarity:"Polarité",Centrality:"Centralité",Subjectivity:"Subjectivité","Très positif":"Très positif",Positif:"Positif",Neutre:"Neutre","Négatif":"Négatif","Très négatif":"Très négatif","Non applicable":"Non applicable","Très central":"Très central",Secondaire:"Secondaire","Non abordé":"Non abordé",1:"Très objectif",2:"Plutôt objectif",3:"Mixte",4:"Plutôt subjectif",5:"Très subjectif","Zoom in":"Zoom avant","Zoom out":"Zoom arrière","Reset view":"Réinitialiser la vue","Toggle legend":"Afficher/masquer la légende","Toggle fullscreen":"Basculer en plein écran","Show all labels":"Afficher toutes les étiquettes","Name the connections":"Nommer les liens","Freeze the layout":"Figer la disposition","Release the nodes you moved":"Libérer les nœuds déplacés","Filter by entity type":"Filtrer par type d’entité","Drag to move it":"Faites-le glisser pour le déplacer","Click to see its connections":"Cliquez pour voir ses liens","Open the record":"Ouvrir la fiche",Close:"Fermer",shared_items_count:"{count} documents en commun",connections_count:"{count} liens",one_connection:"1 lien",and_n_more:"et {count} autres",View:"Vue","Network view":"Réseau","Relational list":"Liste relationnelle","Over time":"Dans le temps","All entities":"Toutes","Number shown":"Nombre affiché",Period:"Période","Five-year periods":"Périodes de cinq ans",Decades:"Décennies","Distinctiveness ranking":"Classement par spécificité","Associated entities over time":"Entités associées dans le temps","Overall mentions":"Mentions au total",shared_items_in_period:"{count} documents en commun, {period}","Ranked by distinctiveness. Curves connect entities that repeatedly appear together.":"Classement par spécificité. Les courbes relient les entités qui reviennent ensemble.","Rows retain the overall distinctiveness ranking. Each cell counts shared items with a readable year.":"Les lignes conservent le classement général par spécificité. Chaque cellule compte les documents en commun dont l’année est lisible.","Darker cells represent more shared items.":"Les cellules plus foncées correspondent à davantage de documents en commun.","Items without a readable year are omitted: {count}.":"Les documents sans année lisible sont omis : {count}.","Network graph. Use the arrow keys to move between connected entities and Enter to select one.":"Graphe de réseau. Utilisez les flèches pour circuler entre les entités reliées et Entrée pour en sélectionner une.","Network of the entities most associated with this record. Use the arrow keys to move between them and Enter to select one.":"Réseau des entités les plus associées à cette notice. Utilisez les flèches pour circuler entre elles et Entrée pour en sélectionner une.","Network of the entities this article is tagged with and the articles sharing them. Use the arrow keys to move between them and Enter to select one.":"Réseau des entités balisées dans cet article et des articles qui les partagent. Utilisez les flèches pour circuler entre elles et Entrée pour en sélectionner une.",entity_type_center:"Centre",entity_type_Personnes:"Personnes",entity_type_Organisations:"Organisations",entity_type_Lieux:"Lieux",entity_type_Sujets:"Sujets","entity_type_Événements":"Événements",entity_type_article:"Article de presse","Context network":"Réseau contextuel","Further reading":"Pour aller plus loin",desc_article_context_network:"Cet article est au centre, entouré des personnes, lieux, organisations et sujets qui y sont balisés. Les articles qui partagent plusieurs de ces balises apparaissent en périphérie. Faites glisser un nœud pour réorganiser le graphe ou cliquez dessus pour voir ses liens et accéder à sa fiche.",desc_article_further_reading:"D’autres documents de la collection qui se rattachent à cet article. Les onglets permettent de changer de manière de les trouver.",desc_further_reading_tags:"Articles balisés avec les mêmes personnes, lieux, organisations ou sujets que celui-ci. Le badge indique combien de balises ils ont en commun.",desc_further_reading_scholarship:"Travaux scientifiques de la bibliographie IWAC dont le texte se lit comme cet article, autrement dit la littérature savante autour de ce dont il traite. Il s’agit de la même comparaison par IA que l’onglet précédent, appliquée d’une collection à l’autre. À considérer comme une piste à explorer plutôt que comme une référence, un travail long comparé de manière synthétique pouvant sembler proche de nombreux articles à la fois.",desc_further_reading_content:"Articles dont le texte intégral se lit comme celui-ci, même sans balise en commun. La comparaison est faite par un modèle d’IA qui transforme chaque article en une empreinte numérique, appelée « plongement sémantique », puis rapproche ces empreintes. Le badge indique la proximité.",Similarity:"Similarité",Shares:"Partage",shares_n_entities:"{count} balises partagées","No related articles":"Aucun article avec des balises communes","No further reading found":"Aucun autre article à suggérer","No entities tagged":"Aucune entité associée à cet article","By shared tags":"Par balises communes","By similar content":"Par contenu similaire","In the scholarship":"Dans la littérature","No related scholarship":"Aucun travail scientifique proche","Corpus A":"Corpus A","Corpus B":"Corpus B","Newspaper articles":"Articles de presse","Islamic publications":"Publications islamiques",Scope:"Périmètre",Selection:"Sélection","Whole country":"Pays entier","Single newspaper":"Un seul journal","Choose two corpora to compare":"Choisissez deux corpus à comparer","Subject overlap":"Chevauchement des sujets","Spatial coverage overlap":"Chevauchement des lieux couverts","Timeline (items per year)":"Chronologie (items par année)","Top subjects (combined top 15)":"Principaux sujets (top 15 combiné)","Most frequent words":"Mots les plus fréquents","Newspapers within each corpus":"Journaux dans chaque corpus",Shared:"Communs","Only in A":"Seulement dans {name}","Only in B":"Seulement dans {name}","No overlap":"Aucun chevauchement","Places mentioned":"Lieux mentionnés","Unique subjects":"Sujets distincts","Period covered":"Période couverte","Single-newspaper corpus — no breakdown":"Corpus à un seul journal, pas de détail","Geographic comparison":"Comparaison géographique","Places mentioned in each corpus, joined to the IWAC authority index. Bubble size scales with the number of items that tagged each place.":"Lieux mentionnés dans chaque corpus, reliés à l’index d’autorité IWAC. La taille de la bulle est proportionnelle au nombre d’articles où ce lieu est balisé.",mentions:"mentions","Open entity":"Ouvrir la fiche","AI sentiment comparison":"Comparaison des sentiments (IA)","Distribution of polarity and centrality in articles of each corpus, as rated by the AI models. The picker swaps the model; publications are not rated.":"Distribution de la polarité et de la centralité des articles de chaque corpus, évaluées par les modèles d’IA. Le sélecteur change de modèle ; les publications ne sont pas évaluées.",Axis:"Axe",Model:"Modèle","Sentiment only on articles":"Sentiments uniquement sur les articles","Model comparison":"Comparaison des modèles","Show reasoning":"Voir les justifications","Not rated":"Non évalué","Very positive":"Très positif",Positive:"Positif",Neutral:"Neutre",Negative:"Négatif","Very negative":"Très négatif","Not applicable":"Non applicable","Very central":"Très central",Central:"Central",Secondary:"Secondaire",Marginal:"Marginal","Not addressed":"Non abordé","Very objective":"Très objectif","Rather objective":"Plutôt objectif",Mixed:"Mixte","Rather subjective":"Plutôt subjectif","Very subjective":"Très subjectif","Scales: polarity 1 (very negative) – 5 (very positive) · centrality 1 (not addressed) – 5 (very central) · subjectivity 1 (objective) – 5 (subjective)":"Échelles : polarité 1 (très négatif) – 5 (très positif) · centralité 1 (non abordé) – 5 (très central) · subjectivité 1 (objectif) – 5 (subjectif)","Show choropleth":"Afficher la choroplèthe","Show bubbles":"Afficher les bulles","Toggle choropleth view":"Basculer la vue choroplèthe",Bubbles:"Bulles","Show point bubbles":"Afficher les bulles ponctuelles","Diverging A minus B":"Carte divergente A moins B","Loading visualisations":"Chargement des visualisations","Activity over time":"Activité dans le temps","Other items in this collection":"Autres éléments de cette collection","Visually similar photographs":"Photographies visuellement similaires",desc_minimal_sparkline:"Où cet élément se situe dans la chronologie d’activité de sa collection. Le point indique l’année de l’élément courant.",desc_minimal_similar:"Autres éléments du même sous-ensemble IWAC, du plus récent au plus ancien. Cliquez sur un élément pour ouvrir sa fiche.",desc_minimal_similar_semantic:"Photographies qu’un modèle d’IA lit comme les plus proches de celle-ci. Il compare les images elles-mêmes, si bien que la ressemblance est visuelle et thématique plutôt qu’une affaire de notices communes. Le pourcentage indique le score de similarité.","Activity of this source over time":"Activité de cette source dans le temps","More from this source":"Autres contenus de cette source",desc_minimal_sparkline_scoped:"Le rythme de publication de cette chaîne ou de cette collection, année par année. Le point indique l’année de l’élément courant.",desc_minimal_similar_scoped:"Autres enregistrements de la même chaîne ou de la même collection, du plus récent au plus ancien. Cliquez sur l’un d’eux pour ouvrir sa fiche.",items_from_source:"{count} éléments de {source}",hours_count:"{count} h",minutes_count:"{count} min",Items:"Éléments",Videos:"Vidéos","Total runtime":"Durée totale","Median length":"Durée médiane","Watch on YouTube":"Regarder sur YouTube","Loading Topic Explorer":"Chargement de l’explorateur de thèmes","Topic distribution":"Distribution des thèmes","All topics":"Tous les thèmes",Topic:"Thème",Topics:"Thèmes","Articles classified":"Articles classifiés",Outliers:"Hors thème","Back to all topics":"Retour à tous les thèmes",cal_panel_title:"Calendrier de publication",topic_copy_link:"Copier le lien vers ce thème",topic_link_copied:"Lien copié","Top countries":"Principaux pays","Most representative articles":"Articles les plus représentatifs","Top values":"Valeurs principales",desc_horizontal_bar:"Valeurs principales triées de la plus élevée à la plus basse.",desc_topic_treemap:"Chaque rectangle est l’un des 30 thèmes dégagés par le modèle ; sa surface reflète le nombre d’articles qui lui ont été rattachés. Cliquez sur un rectangle pour ouvrir le thème en détail.",desc_topic_calendar:"Dates de parution des articles classés dans ce thème. Seuls les articles dont la date est complète, jusqu’au jour, figurent ici ; ceux datés d’une année ou d’un mois seulement sont écartés plutôt que ramenés au 1er janvier.",desc_topic_countries:"Répartition des articles de ce thème par pays de publication.",desc_topic_newspapers:"Journaux et périodiques où ce thème apparaît le plus souvent.",desc_topic_top_articles:"Articles que le modèle a rattachés le plus fortement à ce thème, classés selon sa confiance.","Spatial coverage":"Couverture spatiale",desc_article_spatial:"Lieux associés à cet article, localisés via l’index d’autorité IWAC. Chaque point correspond à un lieu mentionné une fois : tous les points ont donc la même taille. Cliquez sur un point pour ouvrir la fiche du lieu.",article_place_subtitle:"Mentionné dans cet article","No geocoded places":"Aucun lieu de cet article n’a pu être localisé",Publisher:"Éditeur",DOI:"DOI","This work in the bibliography":"Ce travail dans la bibliographie","Closest works in the bibliography":"Travaux les plus proches dans la bibliographie","Press coverage this resembles":"Couverture de presse comparable",desc_reference_activity:"Position de ce travail dans la chronologie de publication de la bibliographie IWAC. Le point indique son année.",desc_reference_similar:"Travaux de la bibliographie dont le texte se lit le plus comme celui-ci, rapprochés par un modèle d’IA plutôt que par vedettes-matière communes. Seuls les travaux dont le texte intégral a été extrait peuvent apparaître, soit environ la moitié de la bibliographie.",desc_reference_press:"Articles de presse de la collection dont le texte se lit comme ce travail, autrement dit la couverture médiatique de ce qu’il étudie. Un travail scientifique est long et a été comparé de manière synthétique ; à lire comme des pistes plutôt que comme des références.",reference_topic_label:"Thème",reference_topic_model:"Mots-clés de thème générés automatiquement, à partir du modèle « {model} ». Chaque langue a son propre modèle : les numéros de thèmes ne sont pas comparables entre eux.",reference_topic_generated:"Mots-clés de thème générés automatiquement, et non des vedettes-matière validées.",reference_reviews_prefix:"Compte rendu de :",reference_reviewed_by_prefix:"Recensé dans :","Loading distinctive vocabulary":"Chargement du vocabulaire distinctif","Distinctive vocabulary":"Vocabulaire distinctif","Coverage bursts":"Pics de couverture",keyness_title:"Les mots qui distinguent cette partie de la collection",keyness_desc:"Mots employés ici au moins {ratio} fois plus souvent que dans le reste de la collection. Chaque barre indique l’ampleur de l’écart et l’étiquette en donne le facteur. Seuls figurent les écarts peu susceptibles d’être dus au hasard (taux de fausses découvertes de {alpha} ; un mot doit apparaître au moins {min} fois ici pour être retenu). Distinctif ne veut pas dire fréquent : un mot peut être courant partout et ne ressortir nulle part.",keyness_slice_caption:"{slice} : {docs} articles, {tokens} mots, {terms} termes distinctifs.",keyness_axis:"Fois plus fréquent qu’ailleurs (log₂)",keyness_tooltip_ratio:"Employé {ratio} fois plus souvent que dans le reste de la collection",keyness_tooltip_count:"{count} occurrences dans {slice}",keyness_tooltip_stats:"Log-vraisemblance G² {g2}, p corrigé {q}",bursts_title:"Quand la couverture d’un sujet s’est intensifiée",bursts_desc:"Périodes où un sujet a été indexé sur beaucoup plus d’articles que son rythme habituel, environ {s} fois ce rythme ou davantage. Ces épisodes sont repérés automatiquement, sans qu’on ait indiqué au logiciel quoi chercher. Chaque barre correspond à un épisode, et un même sujet peut s’intensifier plusieurs fois. Un sujet doit compter au moins {min} articles indexés pour que son rythme de référence soit assez stable pour servir de comparaison. Un sujet qui entre dans l’index et y reste employé ne compte pas : il s’agit de son apparition dans le vocabulaire de catalogage plutôt que d’une évolution de la couverture.",bursts_caption:"{bursts} épisodes répartis sur {subjects} sujets ({found} sujets sur {tested} testés présentent au moins un pic).",bursts_tooltip_span:"Pic : {start}-{end}",bursts_tooltip_mentions:"{mentions} des {total} articles du sujet se situent dans ce pic",bursts_tooltip_weight:"Intensité du pic : {weight}",topics_over_time_title:"Thèmes au fil du temps",topics_over_time_desc:"Comment l’attention de la presse s’est déplacée entre les thèmes (les 12 plus importants ; le reste est regroupé dans « Autres thèmes »). Cliquez sur une bande pour ouvrir le thème.",topic_other:"Autres thèmes",topics_weighting_dominant:"Thème dominant",topics_weighting_weighted:"Pondéré par probabilité",topics_over_time_dominant_note:"Chaque bande donne la part d’un thème parmi les articles dont il est le meilleur libellé unique pour l’année ; le total de chaque année fait donc 100 %. Un article que le modèle répartit à parts égales entre trois thèmes est compté entièrement pour l’un d’eux.",topics_over_time_weighted_note:"Chaque bande correspond à la probabilité moyenne attribuée par le modèle à ce thème sur les articles de l’année ; un article réparti à parts égales contribue donc à ses trois thèmes. Seuls les {k} thèmes principaux de chaque article sont enregistrés, si bien que l’empilement plafonne autour de {mass} % et non à 100 %. L’écart correspond à une masse thématique trop dispersée pour être enregistrée, et non à des articles laissés sans classement.","Calendar heatmap":"Calendrier thermique","Co-occurrence chord":"Cordes de co-occurrence","Profile comparison":"Comparaison des profils","Activity sparkline":"Courbe d’activité","Related articles":"Articles similaires",Sunburst:"Cercles concentriques",Treemap:"Carte proportionnelle",Untitled:"Sans titre","No similar articles":"Aucun article similaire",desc_calendar_heatmap:"Densité des parutions dans le temps. Plus la case est sombre, plus le nombre est élevé. Les couleurs sont celles des autres cartes de chaleur du site, afin que les deux se lisent ensemble.",cal_view_month:"Par mois",cal_view_day:"Par jour",cal_view_hijri:"Par mois hégirien",cal_hijri_era:"H.",cal_month_note:"Une colonne par année, une ligne par mois du calendrier.",cal_day_note:"Une cellule par jour, un bloc par année. Utile pour repérer la poussée qui entoure un événement précis, au prix de beaucoup de grille vide.",cal_hijri_note:"Dates de parution converties dans le calendrier hégirien selon les tables d’Umm al-Qura : le ramadan et dhou al-hijja tiennent ainsi une ligne fixe au lieu de glisser de onze jours par an sur la grille grégorienne. En Afrique de l’Ouest, le début des mois était fixé par l’observation locale du croissant et tombait souvent un jour avant ou après la date tabulaire ; une cellule en tout début ou toute fin de mois peut donc relever du mois voisin.",cal_skipped_note:"{count} n’ont pas pu être converties et ne sont pas affichées.",cal_hijri_coverage:"Seule une date complète au jour près se convertit en date lunaire : cette grille couvre donc {shown} des {total} mentions qu’affiche la vue grégorienne.",desc_chord:"Liens entre les entités les plus souvent mentionnées dans cet ensemble, disposés en cercle. Plus le ruban est épais, plus les deux entités sont mentionnées ensemble. Seules les 30 entités les mieux reliées sont tracées, pour que le diagramme reste lisible.",desc_radar_profile:"Comparaison côte à côte sur trois axes ou plus. Chaque axe est mis à l’échelle séparément, de sorte que les formes restent comparables même lorsqu’une mesure dépasse largement les autres.",desc_sibling_sparkline:"Activité dans le temps de la collection parente, par exemple cet article dans la chronologie de son journal. Le point indique l’élément courant.",desc_similar_items:"Articles dont le texte intégral est, pour un modèle d’IA, le plus proche de celui-ci, classés selon la proximité de la correspondance. Les correspondances faibles sont masquées, afin que les articles très courts ne produisent pas de voisins trompeurs.",desc_sunburst:"Décomposition par niveaux, en anneaux concentriques. Chaque anneau est un niveau et plus l’arc est long, plus le nombre est élevé.",desc_treemap:"Décomposition par niveaux, en rectangles imbriqués. Cliquez sur un rectangle pour l’ouvrir ; le fil d’Ariane en bas permet de remonter.","Loading index overview":"Chargement de la vue d’ensemble de l’index","Entity Index Explorer":"Explorateur d’entités","Keyword Explorer":"Explorateur de mots-clés","Explore the prevalence of Dublin Core Subject and Spatial Coverage fields over time.":"À quelle fréquence les mots-clés Sujet et Couverture spatiale de la collection sont employés au fil du temps. Ces comptes mesurent l’indexation et non la formulation : une notice indexée « Terrorisme » ajoute une seule mention à son année, quel que soit le nombre d’occurrences du mot dans le texte.","Entities by type":"Entités par type","Top entities":"Entités les plus fréquentes dans les champs Sujet et Couverture spatiale (Dublin Core)","Lifespan × frequency":"Durée de vie × fréquence","Temporal extent":"Étendue temporelle","Index table":"Table de l’index",desc_top_entities:"Notices d’autorité apparaissant le plus souvent dans les champs Dublin Core Sujet (dcterms:subject) et Couverture spatiale (dcterms:spatial) des notices de la collection. Cliquez sur une barre pour ouvrir la fiche de l’entité.",desc_lifespan:"Chaque point est une entité. L’axe horizontal donne l’étendue en années entre sa première et sa dernière apparition, l’axe vertical son nombre total de mentions, et la couleur son type. Cliquez sur un point pour ouvrir la fiche.",desc_temporal_extent:"Première et dernière année d’apparition de chaque entité dans le corpus (jusqu’à 30 par type, classées par fréquence). Chaque barre va de la mention la plus ancienne à la plus récente.",desc_places_map:"Deux couches complémentaires sur la même carte. Points d’autorité : chaque lieu de l’index IWAC ayant des coordonnées. Bulles de mentions : fréquence avec laquelle chaque lieu est indiqué dans le champ Dublin Core Couverture spatiale des notices, joint à son point d’autorité par le nom. Cliquez sur un point pour ouvrir la fiche du lieu.","Total entities":"Entités au total","With coordinates":"Avec coordonnées","Span (years)":"Durée (années)",Frequency:"Fréquence","Both layers":"Les deux couches","Authority pins":"Points d’autorité",Layer:"Couche","Spatial Coverage":"Couverture spatiale",Field:"Champ","Facet by":"Filtrer par","By newspaper":"Par journal",Newspaper:"Journal","All newspapers":"Tous les journaux","View mode":"Mode d’affichage","Top frequent":"Plus fréquents",Compare:"Comparer",top_n_keywords:"{count} mots-clés","Number to show":"Nombre à afficher",select_up_to_n:"Sélectionnez jusqu’à {count} mots-clés","Search keywords":"Rechercher des mots-clés","No keywords selected":"Aucun mot-clé sélectionné","Clear selection":"Effacer la sélection","Keywords over time":"Mots-clés dans le temps","All keywords":"Tous les mots-clés",Keyword:"Mot-clé",Occurrences:"Occurrences",Add:"Ajouter",Remove:"Retirer",top_n_over_time:"Top {count} mots-clés dans le temps","Keyword comparison":"Comparaison de mots-clés","Filtered by country: {country}":"Filtré par pays : {country}","Filtered by newspaper: {newspaper}":"Filtré par journal : {newspaper}","All data (global)":"Toutes les données (global)","Select keywords to compare":"Sélectionnez des mots-clés à comparer","Rising and falling subjects":"Sujets montants et descendants",desc_subjects_bump:"Rang des principaux sujets dans chaque décennie. Une ligne qui monte est un sujet qui gagne du terrain sur ceux qui le suivent. Une ligne s’interrompt quand le sujet sort des huit premiers de la décennie ; survolez une décennie pour les rangs et les comptes.","Geographic attention over time":"Attention géographique au fil du temps",desc_geo_attention:"L’attention accordée par la presse à chaque pays au fil du temps, mesurée par la fréquence à laquelle les articles ont été catalogués comme le concernant. Faites glisser le curseur des années ou lancez la lecture. L’échelle de couleurs est identique chaque année, si bien qu’un pays plus sombre signifie toujours une couverture plus forte, quelle que soit l’année affichée.",Play:"Lecture",Pause:"Pause","Entity type":"Type d’entité","Pick an entity":"Choisir une entité","Search entities":"Rechercher des entités","No matches":"Aucun résultat",spatial_pick_hint:"Choisissez une entité pour cartographier les lieux mentionnés à ses côtés. Sans sélection, la carte montre tous les lieux de la collection.",places_count:"{count} lieux","View item page":"Voir la fiche de l’élément","Top places":"Principaux lieux","Map mode":"Mode de carte","Place bubbles":"Bulles de lieux","Country choropleth":"Choroplèthe par pays","Administrative choropleth":"Choroplèthe administrative","Country focus":"Focus pays","Whole world":"Monde entier","Admin level":"Niveau administratif",Regions:"Régions",Region:"Région",Prefectures:"Préfectures",Prefecture:"Préfecture",Scale:"Échelle",Quantile:"Quantile",Linear:"Linéaire","Square root":"Racine carrée","Places map":"Carte des lieux",spatial_map_description:"Plus la bulle est grande, plus le lieu est souvent mentionné. Survolez un lieu pour un aperçu ou cliquez dessus pour la liste complète des éléments.",admin_units_count:"{count} unités","No administrative data":"Aucune donnée administrative","No mapped places":"Aucun lieu cartographié","Click for details":"Cliquer pour les détails",more_items_click:"{count} de plus — cliquer pour la liste complète",items:"éléments","Co-occurrence network":"Réseau de cooccurrences",networks_description:"Les entités qui apparaissent dans les mêmes éléments, d’autant plus proches qu’elles sont souvent mentionnées ensemble. Cliquez sur un nœud pour voir ses liens.","About this network":"À propos de ce réseau",network_select_hint:"Cliquez sur un nœud pour voir ses cooccurrences les plus fortes ; cliquez sur le fond pour effacer.",network_stats_entities:"{nodes} entités · {links} liens",network_stats_places:"{nodes} lieux · {links} liens",network_links_note:"Un lien relie deux entités qui apparaissent dans le même élément au moins {count} fois.","Strongest co-occurrences":"Cooccurrences les plus fortes",cooccurrence_title:"Cooccurrence dans {count} éléments",more_links_count:"+{count} liens supplémentaires",links_count:"{count} liens","Min. link strength":"Force min. des liens","All links":"Tous les liens","Find in network":"Chercher dans le réseau"}};e.t=function(s,i){var a=(t[e.locale]||t.en)[s]||(void 0!==t.en[s]?t.en[s]:s);return i&&(a=a.replace(/\{(\w+)\}/g,function(e,t){return null!=i[t]?i[t]:"{"+t+"}"})),a},e.formatNumber=function(t){if("undefined"!=typeof Intl&&Intl.NumberFormat)try{return new Intl.NumberFormat("fr"===e.locale?"fr-FR":"en-US").format(t)}catch(e){}return String(t)},e.addTranslations=function(e,s){t[e]||(t[e]={}),Object.keys(s).forEach(function(i){t[e][i]=s[i]})}}();